class UnionFind:
    def __init__(self, n):
        self.p = list(range(n))
        self.count = n
    def find(self, i):
        if self.p[i] == i:
            return i
        self.p[i] = self.find(self.p[i])
        return self.p[i]
    def union(self, i, j):
        pi, pj = self.find(i), self.find(j)
        if pi != pj:
            self.p[pi] = pj
            self.count -= 1
            return True
        return False

class Solution:
