#include <vector>
#include <algorithm>
#include <numeric>

struct DSU {
    std::vector<int> p;
    int count;
    DSU(int n) : p(n), count(n) { std::iota(p.begin(), p.end(), 0); }
    int find(int i) { return p[i] == i ? i : (p[i] = find(p[i])); }
    bool unite(int i, int j) {
        int pi = find(i), pj = find(j);
        if (pi != pj) { p[pi] = pj; count--; return true; }
        return false;
    }
};

class Solution {
public:
    std::vector<std::vector<int>> findCriticalAndPseudoCriticalEdges(int n, std::vector<std::vector<int>>& edges) {
        int m = edges.size();
        std::vector<std::vector<int>> indexedEdges(m);
        for (int i = 0; i < m; ++i) {
            indexedEdges[i] = {edges[i][0], edges[i][1], edges[i][2], i};
        }
        std::sort(indexedEdges.begin(), indexedEdges.end(), [](const auto& a, const auto& b) {
            return a[2] < b[2];
        });
        auto getMst = [&](int exclude, int include) -> int {
            DSU dsu(n);
            int weight = 0;
            if (include != -1) {
                dsu.unite(edges[include][0], edges[include][1]);
                weight += edges[include][2];
            }
            for (const auto& e : indexedEdges) {
                if (e[3] == exclude) continue;
                if (dsu.unite(e[0], e[1])) weight += e[2];
            }
            return dsu.count == 1 ? weight : 1e9;
        };
        int base = getMst(-1, -1);
        std::vector<int> critical, pseudo;
        for (int i = 0; i < m; ++i) {
            if (getMst(i, -1) > base) critical.push_back(i);
            else if (getMst(-1, i) == base) pseudo.push_back(i);
        }
        return {critical, pseudo};
    }
};

import java.util.*;

class Solution {
    static class DSU {
        int[] p;
        int count;
        DSU(int n) {
            p = new int[n];
            for (int i = 0; i < n; i++) p[i] = i;
            count = n;
        }
        int find(int i) { return p[i] == i ? i : (p[i] = find(p[i])); }
        boolean union(int i, int j) {
            int pi = find(i), pj = find(j);
            if (pi != pj) { p[pi] = pj; count--; return true; }
            return false;
        }
    }
    public List<List<Integer>> findCriticalAndPseudoCriticalEdges(int n, int[][] edges) {
        int m = edges.length;
        Integer[] order = new Integer[m];
        for (int i = 0; i < m; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(edges[a][2], edges[b][2]));
        int base = getMst(n, edges, order, -1, -1);
        List<Integer> critical = new ArrayList<>();
        List<Integer> pseudo = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            if (getMst(n, edges, order, i, -1) > base) {
                critical.add(i);
            } else if (getMst(n, edges, order, -1, i) == base) {
                pseudo.add(i);
            }
        }
        return Arrays.asList(critical, pseudo);
    }
    private int getMst(int n, int[][] edges, Integer[] order, int exclude, int include) {
        DSU dsu = new DSU(n);
        int weight = 0;
        if (include != -1) {
            dsu.union(edges[include][0], edges[include][1]);
            weight += edges[include][2];
        }
        for (int idx : order) {
            if (idx == exclude) continue;
            if (dsu.union(edges[idx][0], edges[idx][1])) {
                weight += edges[idx][2];
            }
        }
        return dsu.count == 1 ? weight : 1000000000;
    }
}

var findCriticalAndPseudoCriticalEdges = function(n, edges) {
    const m = edges.length;
    const indexed = edges.map((e, i) => [e[0], e[1], e[2], i]);
    indexed.sort((a, b) => a[2] - b[2]);
    function getMst(exclude, include) {
        const p = Array.from({ length: n }, (_, i) => i);
        let count = n;
        function find(i) { return p[i] === i ? i : (p[i] = find(p[i])); }
        function union(i, j) {
            const pi = find(i), pj = find(j);
            if (pi !== pj) { p[pi] = pj; count--; return true; }
            return false;
        }
        let weight = 0;
        if (include !== -1) {
            union(edges[include][0], edges[include][1]);
            weight += edges[include][2];
        }
        for (const [u, v, w, i] of indexed) {
            if (i === exclude) continue;
            if (union(u, v)) weight += w;
        }
        return count === 1 ? weight : 1e9;
    }
    const base = getMst(-1, -1);
    const critical = [];
    const pseudo = [];
    for (let i = 0; i < m; i++) {
        if (getMst(i, -1) > base) {
            critical.push(i);
        } else if (getMst(-1, i) === base) {
            pseudo.push(i);
        }
    }
    return [critical, pseudo];
};
